import numpy as np
from PIL import Image
im = Image.open('mol_0296.png').convert('L')
full = np.array(im) < 128

def runs_for_row(y, x0=620, x1=1001):
    row = full[y, x0:x1]
    runs = []
    in_run = False
    for x in range(len(row)):
        if row[x] and not in_run:
            start = x; in_run = True
        elif not row[x] and in_run:
            runs.append((x0+start, x0+x-1)); in_run = False
    if in_run: runs.append((x0+start, x0+len(row)-1))
    # merge runs separated by < 3px
    merged = []
    for r in runs:
        if merged and r[0]-merged[-1][1] <= 3:
            merged[-1] = (merged[-1][0], r[1])
        else:
            merged.append(r)
    return merged

for y in range(500, 890, 6):
    rs = runs_for_row(y)
    # filter out tiny runs
    rs = [r for r in rs if r[1]-r[0] >= 3]
    print(y, rs)
